import { Router } from "express";
import { authMiddleware } from "../../middlewares/auth.middleware.js";
import { portalRoleMiddleware } from "../../middlewares/role.middleware.js";
import { upload } from "../../middlewares/upload.middleware.js";
import { uploadFile } from "../../controllers/media/media.controller.js";
import { getInvestorDashboard, getInvestorProfile, updateInvestorProfile, listWatchlist, addToWatchlist, removeFromWatchlist, getInvestorPortfolio, listInvestorInvestments, createInvestorInvestment, listInvestorMeetings, createInvestorMeeting, listInvestorMessages, createInvestorMessage, getInvestorWallet, depositInvestorWallet, withdrawInvestorWallet, listInvestorInvoices, getInvestorAnalytics, getInvestorReports, listInvestorNotifications, markInvestorNotificationRead, markAllInvestorNotificationsRead, listInvestorDocuments, addInvestorDocument, listInvestorSubscriptions, purchaseInvestorSubscription, getInvestorSettings, updateInvestorSettings, listAllFounders, } from "../../controllers/investor/investor.controller.js";
const router = Router();
router.use(authMiddleware);
router.use(portalRoleMiddleware(["investor"]));
router.get("/dashboard", getInvestorDashboard);
router.get("/profile", getInvestorProfile);
router.patch("/profile", updateInvestorProfile);
router.put("/profile", updateInvestorProfile);
router.get("/watchlist", listWatchlist);
router.post("/watchlist", addToWatchlist);
router.delete("/watchlist/:id", removeFromWatchlist);
router.get("/portfolio", getInvestorPortfolio);
router.get("/investments", listInvestorInvestments);
router.post("/investments", createInvestorInvestment);
router.get("/meetings", listInvestorMeetings);
router.post("/meetings", createInvestorMeeting);
router.get("/messages", listInvestorMessages);
router.post("/messages", createInvestorMessage);
router.get("/wallet", getInvestorWallet);
router.post("/wallet/deposit", depositInvestorWallet);
router.post("/wallet/withdraw", withdrawInvestorWallet);
router.get("/invoices", listInvestorInvoices);
router.get("/analytics", getInvestorAnalytics);
router.get("/reports", getInvestorReports);
router.get("/notifications", listInvestorNotifications);
router.patch("/notifications/read-all", markAllInvestorNotificationsRead);
router.patch("/notifications/:id/read", markInvestorNotificationRead);
router.get("/documents", listInvestorDocuments);
router.post("/documents", addInvestorDocument);
router.get("/subscription", listInvestorSubscriptions);
router.post("/subscription/purchase", purchaseInvestorSubscription);
router.get("/settings", getInvestorSettings);
router.patch("/settings", updateInvestorSettings);
router.get("/all-founders", listAllFounders);
router.post("/media/upload", upload.single("file"), uploadFile);
export default router;
